param([Parameter(Mandatory = $true)][string]$PassportPath,[Parameter(Mandatory = $true)][string]$TaskId,[Parameter(Mandatory = $true)][string]$GrantId,[Parameter(Mandatory = $true)][string]$TraceId,[Parameter(Mandatory = $true)][string]$TestPlanRef,[Parameter(Mandatory = $true)][string]$SandboxRef,[Parameter(Mandatory = $true)][string]$EvidenceRef,[Parameter(Mandatory = $true)][ValidateSet('passed','failed')][string]$Result,[switch]$PassThru)
$ErrorActionPreference = 'Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$outRoot=[IO.Path]::GetFullPath((Join-Path $root '.qianlima/run-traces/enterprise-tools/trials'))+[IO.Path]::DirectorySeparatorChar;function Emit([object]$v,[int]$c=0){if($PassThru){$v|ConvertTo-Json -Depth 12}else{$v|Format-List};if($c-ne 0){exit $c}};try{$p=Get-Content -LiteralPath ((Resolve-Path -LiteralPath $PassportPath -ErrorAction Stop).Path)-Raw -Encoding UTF8|ConvertFrom-Json}catch{Emit ([ordered]@{status='blocked';reason='tool_passport_invalid';trial_written=$false}) 1};foreach($ref in @($TestPlanRef,$SandboxRef,$EvidenceRef)){if([string]$ref-notmatch'^(?:[a-z][a-z0-9+.-]*://|sha256:)[^\s]+$'){Emit ([ordered]@{status='blocked';reason='trial_reference_required';trial_written=$false}) 1}};$id='trial-'+[Guid]::NewGuid().ToString('n');$path=Join-Path $outRoot ($id+'.json');$r=[ordered]@{schema_version=1;trial_id=$id;passport_id=[string]$p.passport_id;tool_id=[string]$p.tool_id;task_id=$TaskId;grant_id=$GrantId;trace_id=$TraceId;test_plan_ref=$TestPlanRef;sandbox_ref=$SandboxRef;evidence_ref=$EvidenceRef;result=$Result;production_data_used=$false;external_calls=$false;production_write=$false;status='trial_receipt';created_at=[DateTime]::UtcNow.ToString('o')};New-Item -ItemType Directory -Path $outRoot -Force|Out-Null;[IO.File]::WriteAllText($path,($r|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false));Emit ([ordered]@{status='trial_receipt';trial_id=$id;trial_path=$path;production_authority=$false;external_calls=$false})
